from pathlib import Path


def replace_once(path_name: str, old: str, new: str) -> None:
    path = Path(path_name)
    text = path.read_text()
    if new in text:
        return
    if old not in text:
        raise SystemExit(f'{path_name}: expected patch target not found')
    path.write_text(text.replace(old, new, 1))


replace_once(
    'src/dev/rule-influence.ts',
    """  if (inputKey.startsWith('cell.')) {\n    const field = inputKey.slice('cell.'.length);\n    return new RegExp(`^cells\\\\.\\\\d+\\\\.${field.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}$`).test(path);\n  }\n  if (inputKey.startsWith('policy.')) return path === inputKey;\n""",
    """  if (inputKey.startsWith('cell.')) {\n    const field = inputKey.slice('cell.'.length);\n    return new RegExp(`^cells\\\\.\\\\d+\\\\.${field.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}$`).test(path);\n  }\n  if (inputKey.startsWith('population.')) {\n    const field = inputKey.slice('population.'.length).replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    return new RegExp(`^populationGroups\\\\.\\\\d+\\\\.\\\\d+\\\\.(?:${field}|attitudes\\\\.${field})$`).test(path);\n  }\n  if (inputKey.startsWith('policy.')) return path === inputKey;\n""",
)

replace_once(
    'src/dev/rule-analysis.ts',
    """  const inputs = [...readGroups.entries()].map(([key, groupReads]) => ({\n    key,\n    label: groupReads[0].groupLabel,\n    category: groupReads[0].category,\n    reads: groupReads.length,\n    analyzed: analyzedByGroup.get(key) ?? 0,\n    importance: Math.max(\n      0,\n      ...cells.filter(cell => cell.inputKey === key).map(cell => cell.strength),\n    ),\n    example: groupReads[0].example,\n  })).sort((a, b) => b.importance - a.importance || b.reads - a.reads)\n    .slice(0, MAX_INPUT_GROUPS);\n""",
    """  const rankedInputs = [...readGroups.entries()].map(([key, groupReads]) => ({\n    key,\n    label: groupReads[0].groupLabel,\n    category: groupReads[0].category,\n    reads: groupReads.length,\n    analyzed: analyzedByGroup.get(key) ?? 0,\n    importance: Math.max(\n      0,\n      ...cells.filter(cell => cell.inputKey === key).map(cell => cell.strength),\n    ),\n    example: groupReads[0].example,\n  })).sort((a, b) => b.importance - a.importance || b.reads - a.reads);\n  // A policy/global input is part of the rule's causal contract even when a discrete cohort\n  // threshold makes its local derivative zero in this particular snapshot. Keep those direct\n  // reads visible, then spend the remaining display budget on the strongest contextual inputs.\n  const contractInputs = rankedInputs.filter(input =>\n    input.category === 'policy' || input.category === 'budget'\n      || input.category === 'global' || input.category === 'event');\n  const contextualInputs = rankedInputs.filter(input => !contractInputs.includes(input));\n  const inputs = [...contractInputs, ...contextualInputs].slice(0, MAX_INPUT_GROUPS);\n""",
)

path = Path('tests/rules.test.ts')
text = path.read_text()
anchor = """const near = (actual: number, expected: number, tolerance = 1e-7) => assert.ok(Math.abs(actual - expected) <= tolerance, `${actual} != ${expected}`);\n"""
helper = """const near = (actual: number, expected: number, tolerance = 1e-7) => assert.ok(Math.abs(actual - expected) <= tolerance, `${actual} != ${expected}`);\nconst migrationFlow = (game: Game, from: number, to: number, draw: number) => effects(\n  migrationRule, game, () => draw,\n).filter(effect => (effect.kind === 'transfer' || effect.kind === 'population-transfer')\n  && effect.from === from && effect.to === to);\nconst averageMigrants = (game: Game, from: number, to: number, samples = 80) => {\n  let total = 0;\n  for (let index = 0; index < samples; index += 1) {\n    const draw = (index + 0.5) / samples;\n    total += migrationFlow(game, from, to, draw)\n      .filter(effect => effect.kind === 'population-transfer')\n      .reduce((sum, effect) => sum + effect.amount, 0);\n  }\n  return total / samples;\n};\n"""
if helper not in text:
    if anchor not in text:
        raise SystemExit('rules helper anchor changed')
    text = text.replace(anchor, helper, 1)

old_block = """test('migration moves population and proportional savings toward appeal; movement law scales both', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  a.happiness = 0; b.happiness = 1;\n  const flow = (game: Game) => effects(migrationRule, game).filter(e =>\n    (e.kind === 'transfer' || e.kind === 'population-transfer') && e.from === a.id && e.to === b.id);\n  const open = flow(g);\n  const residents = open.filter(e => e.kind === 'population-transfer')\n    .reduce((sum, effect) => sum + effect.amount, 0);\n  const savings = open.find(e => e.kind === 'transfer' && e.resource === 'cash');\n  assert.ok(residents > 0 && savings && savings.kind === 'transfer');\n  near(savings.amount, residents * a.cash / a.population);\n  const closed = structuredClone(g); closed.model.policy.laws.freeMovement = false;\n  const restricted = flow(closed).filter(e => e.kind === 'population-transfer')\n    .reduce((sum, effect) => sum + effect.amount, 0);\n  assert.ok(restricted > 0);\n  near(restricted, residents * .08);\n});\n\ntest('migration follows local earning opportunities when other conditions match', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  for (const c of [a, b]) Object.assign(c, { population: 200, cash: 8000, happiness: .65, employment: .9, foodSecurity: 1, price: 1 });\n  a.output = 400; b.output = 1600;\n  const flow = effects(migrationRule, g).find(e => e.kind === 'population-transfer' && e.from === a.id && e.to === b.id);\n  assert.ok(flow && flow.kind === 'population-transfer' && flow.amount > 0, 'workers move toward higher cash-generating output');\n});\ntest('migration does not request negative savings transfers from a cash-depleted cell', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  a.cash = -1e-14;\n  a.happiness = .1;\n  b.happiness = 1;\n  const moves = effects(migrationRule, g).filter(e =>\n    (e.kind === 'transfer' || e.kind === 'population-transfer') && e.from === a.id && e.to === b.id);\n  assert.ok(moves.some(e => e.kind === 'population-transfer' && e.amount > 0));\n  assert.ok(moves.every(e => 'amount' in e && e.amount >= 0));\n});\n\ntest('high food costs or shortages can reverse an output advantage', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  for (const c of [a, b]) Object.assign(c, { population: 200, cash: 8000, happiness: .65, employment: .9, foodSecurity: 1, price: 1 });\n  a.output = 400; b.output = 1600;\n  b.price = 5;\n  const expensive = effects(migrationRule, g).find(e => e.kind === 'population-transfer' && e.from === b.id && e.to === a.id);\n  assert.ok(expensive && expensive.kind === 'population-transfer' && expensive.amount > 0, 'purchasing power matters more than nominal output');\n  b.price = 1; b.foodSecurity = 0;\n  const hungry = effects(migrationRule, g).find(e => e.kind === 'population-transfer' && e.from === b.id && e.to === a.id);\n  assert.ok(hungry && hungry.kind === 'population-transfer' && hungry.amount > 0, 'workers leave a place where they cannot eat');\n});\n"""
new_block = """test('migration moves population and proportional savings toward appeal; movement law scales expected flow', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  a.happiness = 0; b.happiness = 1;\n  const openOnce = migrationFlow(g, a.id, b.id, 0);\n  const residents = openOnce.filter(e => e.kind === 'population-transfer')\n    .reduce((sum, effect) => sum + effect.amount, 0);\n  const savings = openOnce.find(e => e.kind === 'transfer' && e.resource === 'cash');\n  assert.ok(residents > 0 && savings && savings.kind === 'transfer');\n  near(savings.amount, residents * a.cash / a.population);\n\n  const closed = structuredClone(g);\n  closed.model.policy.laws.freeMovement = false;\n  const openExpected = averageMigrants(g, a.id, b.id);\n  const restrictedExpected = averageMigrants(closed, a.id, b.id);\n  assert.ok(openExpected > 0 && restrictedExpected > 0);\n  near(restrictedExpected / openExpected, .08, .03);\n});\n\ntest('migration follows local earning opportunities when other conditions match', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  for (const c of [a, b]) Object.assign(c, { population: 200, cash: 8000, happiness: .65, employment: .9, foodSecurity: 1, price: 1 });\n  a.output = 400; b.output = 1600;\n  const flow = migrationFlow(g, a.id, b.id, 0).find(e => e.kind === 'population-transfer');\n  assert.ok(flow && flow.kind === 'population-transfer' && flow.amount > 0, 'workers move toward higher cash-generating output');\n});\n\ntest('migration does not request negative savings transfers from a cash-depleted cell', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  a.cash = -1e-14;\n  a.happiness = .1;\n  b.happiness = 1;\n  const moves = migrationFlow(g, a.id, b.id, 0);\n  assert.ok(moves.some(e => e.kind === 'population-transfer' && e.amount > 0));\n  assert.ok(moves.every(e => 'amount' in e && e.amount >= 0));\n});\n\ntest('high food costs or shortages can reverse an output advantage', () => {\n  const g = tiny(), a = g.model.cells.find(c => c.biome !== 'water' && g.model.neighbors[c.id].length)!;\n  const b = g.model.cells[g.model.neighbors[a.id][0]];\n  for (const c of [a, b]) Object.assign(c, { population: 200, cash: 8000, happiness: .65, employment: .9, foodSecurity: 1, price: 1 });\n  a.output = 400; b.output = 1600;\n  b.price = 5;\n  const expensive = migrationFlow(g, b.id, a.id, 0).find(e => e.kind === 'population-transfer');\n  assert.ok(expensive && expensive.kind === 'population-transfer' && expensive.amount > 0, 'purchasing power matters more than nominal output');\n  b.price = 1; b.foodSecurity = 0;\n  const hungry = migrationFlow(g, b.id, a.id, 0).find(e => e.kind === 'population-transfer');\n  assert.ok(hungry && hungry.kind === 'population-transfer' && hungry.amount > 0, 'workers leave a place where they cannot eat');\n});\n"""
if old_block not in text:
    raise SystemExit('migration rules test block changed')
path.write_text(text.replace(old_block, new_block, 1))
